    x: h.oldAgeDependency,
    y: h.pensionGdpPct,
    z: h.outboundRemitRole === "major host" ? 140 : h.outboundRemitRole === "moderate host" ? 90 : 50,
  }));
}

export function vintageDumbbell() {
  return VINTAGE_DELTAS.map((v) => ({
    ...v,
    name: v.short,
  }));
}

