                    type="number"
                    dataKey="x"
                    name="Old-age dep."
                    domain={[0, 60]}
                    tick={{ fill: "#64748b", fontSize: 11 }}
                    label={{
                      value: "Old-age dependency",
                      position: "insideBottom",
                      offset: -4,
                      fill: "#94a3b8",
                      fontSize: 11,
                    }}
                  />
                  <YAxis
                    type="number"
                    dataKey="y"
                    name="Pension % GDP"
                    domain={[0, 18]}
                    tick={{ fill: "#64748b", fontSize: 11 }}
                    label={{
                      value: "Public pension % GDP",
                      angle: -90,
                      position: "insideLeft",
                      fill: "#94a3b8",
                      fontSize: 11,
                    }}
                  />
