                    cursor={{ strokeDasharray: "3 3" }}
                    labelFormatter={(_, payload) =>
                      (payload?.[0]?.payload as { label?: string })?.label ??
                      ""
                    }
                  />
                  <Scatter data={ageScatter}>
                    {ageScatter.map((h) => (
                      <Cell key={h.id} fill={h.fill} />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
