                  <YAxis
                    tick={{ fill: "#64748b", fontSize: 11 }}
                    label={{
                      value: "Old-age dep.",
                      angle: -90,
                      position: "insideLeft",
                      fill: "#94a3b8",
                      fontSize: 11,
